package com.fanzuixianchang.account;
import com.fanzuixianchang.storage.ObjectStore;
import com.fanzuixianchang.core.Problem;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.sql.*;import java.util.*;import java.time.Instant;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class MealPhotosTest {
 static final byte[] PNG={(byte)137,80,78,71,13,10,26,10};
 final ObjectMapper mapper=new ObjectMapper();Connection c;Memory objects;MealPhotos photos;
 static class Memory implements ObjectStore {Map<String,byte[]> data=new HashMap<>();boolean failDelete=false;public boolean enabled(){return true;}public void put(String key,byte[] bytes,String mime){data.put(key,bytes.clone());}public byte[] get(String key,int max){return data.get(key);}public Info head(String key){return new Info("image/png",PNG.length);}public String signedGet(String key,Instant expiry){return "https://unused.invalid";}public void delete(String key){if(failDelete)throw new RuntimeException("provider unavailable");data.remove(key);}}
 @BeforeEach void setup()throws Exception{c=DriverManager.getConnection("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL");try(var q=c.createStatement()){q.execute("CREATE TABLE fanzui_users(user_id VARCHAR(36) PRIMARY KEY,status VARCHAR(16))");q.execute("INSERT INTO fanzui_users VALUES('u1','active'),('u2','active')");q.execute("CREATE TABLE fanzui_user_consents(user_id VARCHAR(36),purpose VARCHAR(40),granted BOOLEAN)");q.execute("INSERT INTO fanzui_user_consents VALUES('u1','meal_cloud_sync',true),('u1','meal_photo_sync',true)");q.execute("CREATE TABLE fanzui_meal_photos(file_id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36),record_id VARCHAR(120),object_key VARCHAR(240),mime_type VARCHAR(32),size_bytes INT,state VARCHAR(16),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");}c.setAutoCommit(false);objects=new Memory();photos=new MealPhotos(objects,mapper);}
 @AfterEach void close()throws Exception{c.close();}
 String upload()throws Exception{String id=photos.stage(c,"u1","meal-1","image/png",PNG.length);c.commit();photos.upload(c,"u1",id,PNG);c.commit();return id;}
 com.fasterxml.jackson.databind.node.ObjectNode record(String id){var payload=mapper.createObjectNode();var array=payload.putArray("cloudImages");if(id!=null)array.addObject().put("fileId",id).put("mimeType","image/png");return payload;}
 @Test void privateReadAndRecordOwnership()throws Exception{String id=upload();photos.attach(c,"u1","meal-1",record(id));c.commit();assertEquals(id,photos.read(c,"u1",id).get("fileId"));c.commit();assertThrows(Problem.class,()->photos.read(c,"u2",id));assertThrows(Problem.class,()->photos.attach(c,"u1","different-meal",record(id)));}
 @Test void explicitConsentAndMimeAreRequired()throws Exception{assertThrows(Problem.class,()->photos.stage(c,"u2","meal-1","image/png",PNG.length));assertThrows(Problem.class,()->MealPhotos.decode("image/jpeg",Base64.getEncoder().encodeToString(PNG)));assertArrayEquals(PNG,MealPhotos.decode("image/png",Base64.getEncoder().encodeToString(PNG)));}
 @Test void replacingPhotoQueuesDeletionAndFailuresRemainRetryable()throws Exception{String id=upload();photos.attach(c,"u1","meal-1",record(id));c.commit();photos.attach(c,"u1","meal-1",record(null));c.commit();objects.failDelete=true;assertThrows(RuntimeException.class,()->photos.cleanup(c));c.rollback();assertEquals(1,objects.data.size());objects.failDelete=false;assertEquals(1,photos.cleanup(c));c.commit();assertTrue(objects.data.isEmpty());assertThrows(Problem.class,()->photos.read(c,"u1",id));}
 @Test void deletingAccountKeepsDurableCleanupJob()throws Exception{String id=upload();photos.queueDelete(c,"u1",null);try(var q=c.createStatement()){q.execute("DELETE FROM fanzui_users WHERE user_id='u1'");}c.commit();assertEquals(1,photos.cleanup(c));assertTrue(objects.data.isEmpty());}
 @Test void oldClientsPreserveReferencesAndOrphansExpire()throws Exception{String id=upload();photos.attach(c,"u1","meal-1",record(id));c.commit();var legacy=mapper.createObjectNode();photos.attach(c,"u1","meal-1",legacy);c.commit();assertEquals(id,legacy.path("cloudImages").get(0).path("fileId").asText());String orphan=upload();try(var q=c.prepareStatement("UPDATE fanzui_meal_photos SET created_at=? WHERE file_id=?")){q.setTimestamp(1,Timestamp.from(Instant.now().minusSeconds(90000)));q.setString(2,orphan);q.executeUpdate();}c.commit();assertEquals(1,photos.cleanup(c));assertEquals(1,objects.data.size());}
}
